terraform {
  required_version = ">= 1.0.0"
  required_providers {
    google = {
      source  = "hashicorp/google"
      version = "~> 8.0"
    }
  }
}

provider "google" {
  # Default project and region can be set here or via environment variables
}

# Cloud Storage bucket configured to transition objects to NEARLINE storage after 30 days
resource "google_storage_bucket" "example" {
  name                        = "example-nearline-lifecycle-bucket"
  location                    = "US"
  storage_class               = "STANDARD"
  uniform_bucket_level_access = true

  lifecycle_rule {
    condition {
      age = 30
    }
    action {
      type          = "SetStorageClass"
      storage_class = "NEARLINE"
    }
  }

  labels = {
    environment = "production"
    managed_by  = "terraform"
  }
}

