# Highly available (regional) MySQL 8.0 Cloud SQL instance
resource "google_sql_database_instance" "mysql_ha" {
  name                = "mysql-8-regional-instance"
  database_version    = "MYSQL_8_0"
  region              = "us-central1"
  deletion_protection = true

  settings {
    # HA requires a standard or custom tier (db-f1-micro and db-g1-small do not support HA)
    tier              = "db-custom-2-8192"
    availability_type = "REGIONAL"

    backup_configuration {
      enabled            = true
      binary_log_enabled = true
    }

    ip_configuration {
      # No authorized networks added by default to enforce least privilege
      ipv4_enabled = true
      ssl_mode     = "ENCRYPTED_ONLY"
    }

    user_labels = {
      environment = "production"
      managed_by  = "terraform"
    }
  }
}

