provider "google" {
  region = "asia-south1"
}

# Dedicated VPC for GKE Autopilot
resource "google_compute_network" "vpc" {
  name                    = "gke-autopilot-vpc"
  auto_create_subnetworks = false
}

# Subnet with secondary IP ranges required for VPC-native GKE clusters
resource "google_compute_subnetwork" "gke_subnet" {
  name                     = "gke-autopilot-subnet"
  ip_cidr_range            = "10.10.0.0/20"
  region                   = "asia-south1"
  network                  = google_compute_network.vpc.id
  private_ip_google_access = true

  secondary_ip_range {
    range_name    = "pods"
    ip_cidr_range = "10.20.0.0/16"
  }

  secondary_ip_range {
    range_name    = "services"
    ip_cidr_range = "10.30.0.0/20"
  }
}

# GKE Autopilot Cluster
# In the google provider, GKE cluster labels are defined via resource_labels.
resource "google_container_cluster" "autopilot_cluster" {
  name     = "gke-autopilot-asia-south1"
  location = "asia-south1"

  enable_autopilot = true

  network    = google_compute_network.vpc.id
  subnetwork = google_compute_subnetwork.gke_subnet.id

  ip_allocation_policy {
    cluster_secondary_range_name  = "pods"
    services_secondary_range_name = "services"
  }

  resource_labels = {
    environment = "prod"
  }

  # Prevent accidental deletion per organizational best practice
  deletion_protection = true
}

