# Dedicated VPC network for the firewall rule
resource "google_compute_network" "default" {
  name                    = "vpc-network"
  auto_create_subnetworks = false
}

# Firewall rule allowing inbound SSH (TCP 22) only from 203.0.113.0/24
resource "google_compute_firewall" "allow_ssh" {
  name        = "allow-ssh-restricted"
  network     = google_compute_network.default.name
  description = "Allows inbound TCP port 22 access strictly from 203.0.113.0/24"
  direction   = "INGRESS"
  priority    = 1000

  allow {
    protocol = "tcp"
    ports    = ["22"]
  }

  source_ranges = ["203.0.113.0/24"]
}

