# Terraform configuration for Cloud Router and Cloud NAT in asia-south1
# to enable outbound internet access for private VMs.

terraform {
  required_version = ">= 1.5.0"
  required_providers {
    google = {
      source  = "hashicorp/google"
      version = "~> 8.0"
    }
  }
}

provider "google" {
  region = "asia-south1"
}

# VPC Network hosting the private resources
resource "google_compute_network" "vpc_network" {
  name                    = "vpc-asia-south1"
  auto_create_subnetworks = false
}

# Private Subnetwork in asia-south1
resource "google_compute_subnetwork" "subnet" {
  name                     = "subnet-asia-south1-private"
  ip_cidr_range            = "10.0.1.0/24"
  region                   = "asia-south1"
  network                  = google_compute_network.vpc_network.id
  private_ip_google_access = true
}

# Cloud Router in asia-south1
resource "google_compute_router" "router" {
  name    = "router-asia-south1"
  region  = google_compute_subnetwork.subnet.region
  network = google_compute_network.vpc_network.id
}

# Cloud NAT Gateway for outbound internet access
resource "google_compute_router_nat" "nat" {
  name                               = "nat-asia-south1"
  router                             = google_compute_router.router.name
  region                             = google_compute_router.router.region
  nat_ip_allocate_option             = "AUTO_ONLY"
  source_subnetwork_ip_ranges_to_nat = "ALL_SUBNETWORKS_ALL_IP_RANGES"

  log_config {
    enable = true
    filter = "ERRORS_ONLY"
  }
}

