# Dedicated service account following the principle of least privilege
resource "google_service_account" "web_sa" {
  account_id   = "web-1-sa"
  display_name = "Service Account for web-1 VM"
}

resource "google_compute_instance" "web_1" {
  name         = "web-1"
  machine_type = "e2-medium"
  zone         = "asia-south1-a"

  boot_disk {
    auto_delete = true
    initialize_params {
      image = "debian-cloud/debian-12"
    }
  }

  network_interface {
    network = "default"
    # Public IP (access_config) omitted for security/least-privilege defaults
  }

  service_account {
    email  = google_service_account.web_sa.email
    scopes = ["cloud-platform"]
  }
}

