resource "google_service_account" "vm_service_account" {
  account_id   = "dedicated-vm-sa"
  display_name = "Dedicated Service Account for VM Instance"
}

# Compute Engine virtual machine with no external IP
resource "google_compute_instance" "vm_instance" {
  name         = "internal-workload-vm"
  zone         = "us-central1-a"
  machine_type = "e2-medium"

  boot_disk {
    initialize_params {
      image = "ubuntu-os-cloud/ubuntu-2204-lts"
      labels = {
        environment = "production"
      }
    }
  }

  network_interface {
    network = "default"

    # NOTE: The access_config block is intentionally omitted.
    # Omitting access_config ensures no external (public) IP address is provisioned.
  }

  service_account {
    # Using the dedicated service account with the standard cloud-platform scope.
    # Specific permissions should be granted to this service account via IAM roles.
    email  = google_service_account.vm_service_account.email
    scopes = ["cloud-platform"]
  }

  labels = {
    environment = "production"
    managed_by  = "terraform"
  }
}

