# Pub/Sub topic for orders
resource "google_pubsub_topic" "orders" {
  name = "orders"

  labels = {
    environment = "production"
    managed_by  = "terraform"
  }
}

# Pull subscription for orders topic with a 30-second acknowledgement deadline.
# Omitting push_config creates a pull subscription by default.
resource "google_pubsub_subscription" "orders_sub" {
  name  = "orders-sub"
  topic = google_pubsub_topic.orders.id

  ack_deadline_seconds = 30

  labels = {
    environment = "production"
    managed_by  = "terraform"
  }
}

