provider "google" {
  # Default provider configuration
}

# Main Pub/Sub topic for incoming messages
resource "google_pubsub_topic" "main" {
  name = "main-topic"
}

# Dead-letter topic to receive messages that fail processing
resource "google_pubsub_topic" "dead_letter" {
  name = "dead-letter-topic"
}

# Pub/Sub subscription configured with a dead-letter policy
# Note: For production use, ensure the Google Cloud Pub/Sub service account
# (service-{project_number}@gcp-sa-pubsub.iam.gserviceaccount.com) has roles/pubsub.publisher
# on the dead-letter topic and roles/pubsub.subscriber on this subscription.
resource "google_pubsub_subscription" "main_subscription" {
  name  = "main-subscription"
  topic = google_pubsub_topic.main.id

  dead_letter_policy {
    dead_letter_topic     = google_pubsub_topic.dead_letter.id
    max_delivery_attempts = 5
  }
}

