# Pub/Sub topic that receives messages from the Cloud Scheduler job
resource "google_pubsub_topic" "daily_job_topic" {
  name = "daily-scheduled-topic"
}

# Cloud Scheduler job configured to trigger every day at 02:00 UTC
resource "google_cloud_scheduler_job" "daily_pubsub_job" {
  name        = "daily-scheduled-job"
  description = "Fires every day at 02:00 and publishes a notification to Pub/Sub"
  schedule    = "0 2 * * *"
  time_zone   = "UTC"

  pubsub_target {
    topic_name = google_pubsub_topic.daily_job_topic.id
    data       = base64encode(jsonencode({ "event" = "daily_run" }))
  }
}

