# BigQuery Dataset
resource "google_bigquery_dataset" "main" {
  dataset_id                  = "analytics_dataset"
  friendly_name               = "Analytics Dataset"
  description                 = "Dataset containing application analytics and event logs."
  location                    = "US"
  default_table_expiration_ms = 31536000000 # 365 days
}

# BigQuery Table: events
resource "google_bigquery_table" "events" {
  dataset_id          = google_bigquery_dataset.main.dataset_id
  table_id            = "events"
  description         = "Table tracking user events"
  deletion_protection = false # Set to true for production to prevent accidental loss

  schema = jsonencode([
    {
      name        = "timestamp"
      type        = "TIMESTAMP"
      mode        = "REQUIRED"
      description = "The time at which the event occurred."
    },
    {
      name        = "user_id"
      type        = "STRING"
      mode        = "REQUIRED"
      description = "Unique identifier for the user triggering the event."
    }
  ])
}

