# KMS KeyRing to logically organize crypto keys
resource "google_kms_key_ring" "keyring" {
  name     = "app-keyring"
  location = "global"
}

# Symmetric CryptoKey configured to rotate automatically every 90 days (7,776,000 seconds)
resource "google_kms_crypto_key" "symmetric_key" {
  name            = "app-symmetric-key"
  key_ring        = google_kms_key_ring.keyring.id
  purpose         = "ENCRYPT_DECRYPT"
  rotation_period = "7776000s" # 90 days (90 * 24 * 60 * 60 seconds)

  labels = {
    environment = "production"
    managed_by  = "terraform"
  }

  lifecycle {
    prevent_destroy = true
  }
}

