# Cloud Storage bucket configured for static website hosting
resource "google_storage_bucket" "static_website" {
  name          = "example-static-website-bucket-unique"
  location      = "US"
  force_destroy = false

  uniform_bucket_level_access = true

  website {
    main_page_suffix = "index.html"
    not_found_page   = "404.html"
  }

  labels = {
    environment = "production"
    purpose     = "static-website"
  }
}

# Grant public read access to all objects in the bucket for static website visitors
resource "google_storage_bucket_iam_member" "public_read" {
  bucket = google_storage_bucket_static_website.name
  role   = "roles/storage.objectViewer"
  member = "allUsers"
}

# Single Terraform configuration for a MySQL Cloud SQL instance with Public IP enabled
# and restricted to the office VPN CIDR range for security.

terraform {
  required_version = ">= 1.5.0"
  required_providers {
    google = {
      source  = "hashicorp/google"
      version = "~> 8.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.5"
    }
  }
}

provider "google" {
  region = "us-central1"
}

# Variable to define the office VPN public IP range for authorized access
variable "office_vpn_cidr" {
  type        = string
  description = "The public IPv4 CIDR range of the office VPN allowed to access Cloud SQL"
  default     = "198.51.100.0/24" # Documentation TEST-NET-2 range; update to actual office VPN CIDR
}

# Suffix to ensure a unique Cloud SQL instance name
resource "random_id" "db_name_suffix" {
  byte_length = 4
}

# Cloud SQL MySQL Instance with Public IP and Authorized Networks configured
resource "google_sql_database_instance" "mysql_instance" {
  name                = "mysql-vpn-instance-${random_id.db_name_suffix.hex}"
  database_version    = "MYSQL_8_0"
  region              = "us-central1"
  deletion_protection = false

  settings {
    tier = "db-n1-standard-1"

    ip_configuration {
      # Enables public IPv4 assignment for the instance
      ipv4_enabled = true

      # Restrict public IP access strictly to the office VPN network
      authorized_networks {
        name  = "office-vpn"
        value = var.office_vpn_cidr
      }
    }
  }
}

# Output the assigned public IP address
output "instance_public_ip_address" {
  description = "The public IPv4 address assigned to the Cloud SQL instance"
  value       = google_sql_database_instance.mysql_instance.public_ip_address
}
